import type { NextConfig } from 'next'

const nextConfig: NextConfig = {
  cacheComponents: true,
}

export default nextConfig

import { cacheLife, cacheTag } from 'next/cache'
import { getAllProducts } from '@/lib/db'

export async function getCatalogProducts() {
  'use cache'
  cacheTag('products')
  cacheLife('max')
  return getAllProducts()
}

import { revalidateTag } from 'next/cache'
import { getCatalogProducts } from '@/lib/catalog'

export default async function Page() {
  const products = await getCatalogProducts()

  async function syncLatestCatalog() {
    'use server'
    // Mark the shared catalog stale and return immediately. Views keep serving
    // the cached list while a background refresh picks up ERP/PIM changes.
    revalidateTag('products', 'max')
  }

  return (
    <main>
      <h1>Product catalog</h1>
      <form action={syncLatestCatalog}>
        <button type="submit">Sync latest catalog</button>
      </form>
      <ul>
        {products.map((product) => (
          <li key={product.id}>
            {product.name} (${product.price})
          </li>
        ))}
      </ul>
    </main>
  )
}

